// A14 职位Tab·看市场 —— 自己刷市场上的职位，每张卡上带「让AI代理去谈」。
//
// 与「在谈」共用顶栏（意向左右平铺切换 + 在谈/看市场子视图）和代理横幅，
// 所以这两屏切换时顶部不动，只有列表在换 —— 这是设计稿里的硬要求。
//
// 卡片版式（2026-08-18 参考 Jobright 岗位卡重排，用户指定）：
//   公司字标 + 公司名/规模行 + 右上适配环 → 大职位名 → 薪资行 → 标签行
//   → 分隔线 → 发布人 + 「让AI代理去谈」。
// 借它的骨架（公司身份先行、匹配分做环形进度、标题放大），但三处按我们的立场改：
//   · 薪资不进标签堆 —— 单独一行 薪资体，价格标地位不动摇；
//   · 适配环按分数换语义色（≥80 翠绿 / 65-79 协调橙 / 更低灰），不是装饰绿；
//   · 底行不放收藏/屏蔽小图标，只放我们的差异点：让AI代理去谈。
//
// 搜索长在这一屏（2026-08-18 补）：顶部意向栏的放大镜只负责打开它。
// 列表 = 当前意向 → 去掉不感兴趣与被屏蔽的 → 过搜索。
//
// 这一屏不做任何本地档位过滤：过滤在本产品里是代理的活，用户写下的是长期规则、
// 不是一次性档位（2026-08-20）；列表里的岗位就是代理按规则筛过之后的结果。
//
// 第二批（2026-09-09 产品负责人「把这个筛选的功能都删了」）：顶栏「筛选 ▾」、页内的
// 「岗位筛选规则」筛选层（规则清单）与「筛选 · N」角标整体删除；写规则的入口只剩
// 规则库（canonical，「我 › AI代理规则库」）。
//
// P4 模式边界：Backend 列表只来自当前活跃意向（scope 坐标 = 当前意向编号 载体里的
// intention_id，且 服务端 status === 'active'）的候选岗位快照，经 从P4候选岗位 投影；
// 不读 市场列表、不做 Mock 屏蔽公司过滤（P4/P3 已在服务端收口）。搜索仍是本地包含
// 匹配；下拉只重读（GET），空态「让AI代理帮我搜」才建新批次（POST+GET）。
// 委托必过显式披露确认（P5：先拿权威附件库 —— 零份去上传、一份 确认层 点名、
// 多份 附件简历选择层 单选），确认不复用；委托后不写任何 Mock 在谈状态、不跳页，
// 进行中回执交给 use发现推荐委托轮询 按节拍刷新。

import { useEffect, useMemo, useRef, useState } from 'react';
import 样式 from './看市场.module.css';
import 下拉刷新 from '../组件/下拉刷新';
import 顶部意向栏, { 取走市场工具请求 } from './顶部意向栏';
import { 主页外壳, 代理横幅, 滚动区, 白卡, 公司字标 } from '../组件/通用';
import 适配环 from '../组件/适配环';
import 确认层 from '../组件/确认层';
import 附件简历选择层, { 从附件行取选择值, type 附件简历选择值 } from '../组件/附件简历选择层';
import { 谈判图标, 放大镜图标 } from '../组件/图标';
import { use应用状态 } from '../状态/应用状态';
import { 取有效当前意向编号 } from '../状态/领域/候选资料';
import { use适配分 } from '../状态/use适配分';
import { use导航, 标记看市场来路 } from '../路由/导航钩子';
import { 路径 } from '../路由/路径表';
import { 市场列表 } from '../数据/模拟数据';
import type { 市场职位 } from '../数据/类型';
import type { BFF附件简历 } from '../数据/BFF契约';
import { 从P4候选岗位, P4已开案, 映射P4委托展示 } from '../数据/发现推荐映射';
import type { P4候选岗位页面 } from '../数据/招聘数据源类型';
import { P4错误文案, P4范围键 } from '../状态/后端/发现推荐操作';
import { P5范围键 } from '../状态/后端/MatchCase操作';
import { 取P5候选横幅状态 } from '../状态/后端/MatchCase统计';
import { P4委托进度未知文案, use发现推荐委托轮询 } from '../状态/后端/use发现推荐委托轮询';
import { 轻提示 } from '../组件/轻提示';

/** 本地包含匹配：职位名、公司名、公司简介、标签四处任一命中即可（原型层不做分词与拼音）*/
function 命中搜索(岗: 市场职位, 关键词: string): boolean {
  if (关键词 === '') return true;
  return [岗.职位, 岗.公司, 岗.公司简介, ...岗.标签].some((文本) =>
    文本.toLowerCase().includes(关键词)
  );
}

/** 候选端委托的业务 pair 键：意向 + 岗位（本次周期集合与按卡忙态共用同一把键）。 */
const 委托键 = (intentionId: string, jobId: string) => `${intentionId}|${jobId}`;

export default function 看市场() {
  const { 状态, 派发, 数据源模式, 后端状态, 操作 } = use应用状态();
  const { 跳转 } = use导航();

  const [搜索展开, 设搜索展开] = useState(false);
  const [搜索词, 设搜索词] = useState('');
  const 搜索框 = useRef<HTMLInputElement>(null);
  // 本次进屏内点过「让AI代理去谈」的岗：卡先留在原位显示委托状态标，
  // 让用户看到这一下点到了；离开这一屏再回来就不再出现（它已经是一张在谈单了）。
  // 与企业端 候选推荐 的 本次已接触 同一写法。
  const 本次已委托 = useRef<Set<string>>(new Set());

  // ── P4：Backend 候选发现 ──────────────────────────────────────
  const 是后端 = 数据源模式 === 'backend';
  // 本次要委托的捕获（P5）：一份附件走 确认层 点名该文件；捕获只在非空时挂载层，
  // 取消即清、确认后立刻清 —— 上一次的披露授权绝不复用
  const [待确认委托, 设待确认委托] = useState<{ 视图: P4候选岗位页面; 选择: 附件简历选择值 } | null>(null);
  // 多份附件走 附件简历选择层：捕获待选的卡与权威库行，取消 / 确认即清
  const [待选择委托, 设待选择委托] = useState<{ 视图: P4候选岗位页面; 文件们: readonly BFF附件简历[] } | null>(null);
  // Task 5：委托忙态按业务 pair（intentionId|jobId）隔离 —— 等一张卡的 POST 时，
  // 其他卡照样能浏览和发起委托；同一张卡连点仍只产生一次请求（操作层另有单飞）。
  const [委托中, 设委托中] = useState<ReadonlySet<string>>(() => new Set());
  // 本次进屏发起过委托的业务 pair。周期 = 主体 + 角色 + scope + 本次挂载：
  // 离屏、切意向（含 A→B→A）、换主体都结束旧周期并清空 —— 切回旧 scope 是新周期，
  // 不恢复它的暂留；刷新后自然为空，由权威推荐摘要恢复成功过滤。
  const 本次委托 = useRef<Set<string>>(new Set());
  const 周期引用 = useRef(0);

  // Backend 的 scope 坐标 = 当前意向编号 载体（水合后端意向 / Backend 切意向 写入的
  // intention_id）；当前意向 本身仍是意向名（Mock 语义不动，名字不唯一不可反查）。
  // 只有服务端 active 的编号才 admits 进市场流，否则不发任何 P4 请求（宁空勿错）。
  const 活跃意向 = 是后端
    ? 取有效当前意向编号(状态.当前意向编号, 状态.求职意向表, 状态.后端意向服务端)
    : null;
  // 只选当前意向自己的快照：键按意向隔离，切换时旧 scope 的数据天然进不来
  const 后端快照 = 活跃意向 !== null ? 后端状态.候选岗位推荐?.[活跃意向] : undefined;

  // 委托准备的代际栅栏（评审 R2）：权威附件库的读取是异步的，回来时用户可能已
  // 切意向（含 A→B→A 往返）或离开本屏 —— 每次卸载与 scope 变化都让代际 +1，迟到
  // 的结果（含拒绝）对不上代际就整体静默作废，绝不跨 scope 弹层/提示/跳转。
  // 代际只在 effect 里动：StrictMode 的 setup→cleanup→setup 不会把它永久关死。
  const 准备代际引用 = useRef(0);
  useEffect(() => () => { 准备代际引用.current += 1; }, []);
  const 当前候选主体 = 后端状态.主体?.last_used_role === 'candidate'
    ? 后端状态.主体.subject_id
    : null;
  useEffect(() => {
    准备代际引用.current += 1;
    // scope 变化即作废已捕获的委托层状态：旧意向的确认层绝不在新意向下出现
    设待确认委托(null);
    设待选择委托(null);
    // 同一下也结束本次进屏的委托周期：暂留集合与按卡忙态一起归零
    周期引用.current += 1;
    本次委托.current = new Set();
    设委托中(new Set());
    return () => {
      周期引用.current += 1;
      本次委托.current = new Set();
    };
  }, [活跃意向, 当前候选主体]);

  const 后端卡们 = useMemo(
    () => (后端快照 ? 后端快照.items.map((卡) => {
      // 委托状态槽只认 映射P4委托展示 的闭合六态投影：摘要 + 权威回执（按 delegation_id 对上）
      const 委托回执 = 卡.delegation === null
        ? null
        : 后端状态.P4委托回执?.[卡.delegation.delegation_id] ?? null;
      return { 视图: 从P4候选岗位(卡), 卡, 展示: 映射P4委托展示(卡.delegation, 委托回执) };
    }) : []),
    [后端快照, 后端状态.P4委托回执]
  );

  // 进屏 / 切意向：先注册可见范围再懒加载（操作层的栅栏要靠注册的可见范围对上）；
  // 离开本屏或换 scope 时把可见范围清成 null，别让详情页等屏背上旧范围。
  useEffect(() => {
    if (!是后端 || 活跃意向 === null) return;
    操作.设置发现推荐范围('candidate', P4范围键.候选列表(活跃意向));
    void 操作.加载候选岗位(活跃意向).catch(() => undefined);
    return () => 操作.设置发现推荐范围('candidate', null);
  }, [是后端, 活跃意向, 操作]);

  // 进行中委托（accepted/evaluating，即 映射P4委托展示.inProgress === true 的那两个状态）
  // 交给页面域轮询钩子；暂停表里的委托把状态文案覆盖成中性「进度未知」—— 绝不伪造终态回执。
  // Mock 不开节拍。
  const 进行中委托 = useMemo(
    () => 后端卡们.flatMap(({ 卡, 展示 }) =>
      展示?.inProgress === true && 卡.delegation !== null
        ? [{
          role: 'candidate' as const,
          delegationId: 卡.delegation.delegation_id,
          // inProgress === true 已闭合出 accepted/evaluating 两员
          state: 展示.state === 'accepted' ? ('accepted' as const) : ('evaluating' as const),
        }]
        : []),
    [后端卡们]
  );
  // terminal summary 单次权威补读：摘要已 refused/failed 而权威回执表缺这条 ID 时，
  // 钩子立即补读一次拿回拒绝/失败码 —— 页面摘要永远不给原因，回执来了才解释
  const 待恢复终态 = useMemo(
    () => 后端卡们.flatMap(({ 卡 }) => {
      const summary = 卡.delegation;
      if (summary === null || summary.delegation_id === '') return [];
      if (summary.state !== 'refused' && summary.state !== 'failed') return [];
      if (后端状态.P4委托回执?.[summary.delegation_id] !== undefined) return [];
      return [{
        role: 'candidate' as const,
        delegationId: summary.delegation_id,
        state: summary.state,
      }];
    }),
    [后端卡们, 后端状态.P4委托回执]
  );
  const 进度未知 = use发现推荐委托轮询({
    开启: 是后端,
    委托: 进行中委托,
    待恢复终态,
    刷新: 操作.刷新委托,
    // scope 变化即结束本轮询周期：换意向不带走上一意向的连续失败计数（§8.3）
    范围键: 活跃意向,
  });

  // 委托第一跳（P5）：先拿权威附件库，再让用户显式选定这次提交的简历坐标。
  // 读失败 → P4 失败 toast（零导航零委托）；null（会话/角色换代）→ 静默返回，
  // 绝不当成空库走「去上传」的跳转分支。
  const 开始委托 = async (视图: P4候选岗位页面) => {
    if (!视图.recommendationId || !视图.intentionId) return;
    const 起始代际 = 准备代际引用.current;
    try {
      const 库 = await 操作.准备候选委托简历();
      // 迟到栅栏：scope 已变或屏幕已卸载 → 本次权威结果整体作废（静默返回）
      if (准备代际引用.current !== 起始代际) return;
      if (库 === null) return;
      if (库.items.length === 0) {
        轻提示('请先上传一份 PDF 简历');
        跳转(路径.我的简历);
        return;
      }
      if (库.items.length === 1) {
        const 唯一 = 库.items[0];
        if (唯一) 设待确认委托({ 视图, 选择: 从附件行取选择值(唯一) });
        return;
      }
      设待选择委托({ 视图, 文件们: 库.items });
    } catch (错误) {
      // 拒绝路径同样过栅栏：切了 scope / 离屏后的迟到失败不再 toast
      if (准备代际引用.current !== 起始代际) return;
      轻提示(P4错误文案(错误));
    }
  };

  // 确认层只在这里真正发起委托：先收层再 await —— 任何失败（含终态/拒绝回执）
  // 都要求下一次点击重新过确认，上一次的披露授权绝不复用。
  const 执行候选委托 = async (视图: P4候选岗位页面, 选择: 附件简历选择值) => {
    if (!视图.recommendationId || !视图.intentionId) return;
    const 键 = 委托键(视图.intentionId, 视图.jobId);
    if (委托中.has(键)) return;
    设待确认委托(null);
    // 记录只表示「这一下是我点的」，不授权成功；显示成功仍要过权威成功谓词
    本次委托.current.add(键);
    设委托中((旧) => new Set(旧).add(键));
    const 起始周期 = 周期引用.current;
    try {
      await 操作.委托候选岗位({
        intentionId: 视图.intentionId,
        recommendationId: 视图.recommendationId,
        jobId: 视图.jobId,
        resumeFileId: 选择.fileId,
        resumeFileVersionId: 选择.fileVersionId,
        disclosureAcknowledged: true,
      });
    } catch (错误) {
      // 迟到栅栏：换意向/主体/离屏后的失败不再打扰新周期
      if (周期引用.current === 起始周期) 轻提示(P4错误文案(错误));
    } finally {
      // 换过周期就不动新周期的忙态（旧 finally 绝不给新请求解锁）
      if (周期引用.current === 起始周期) {
        设委托中((旧) => {
          const 新 = new Set(旧);
          新.delete(键);
          return 新;
        });
      }
    }
  };

  // 下拉只重读当前 scope（GET）；空态的「让AI代理帮我搜」才建新批次（POST+GET）。
  // 下拉把这个 Promise 交回 下拉刷新：转圈等真实 GET settle，不是干等最短动画。
  const 重读当前范围 = () => {
    if (活跃意向 === null) return;
    // 这里的静默不是漏提示：加载失败（含下拉重读）的文案由操作层落进快照 error，
    // 列表上方的错误/未决行负责呈现 —— 再 toast 一次就成了双重提示，别「修」它。
    return 操作.加载候选岗位(活跃意向, true).catch(() => undefined);
  };
  const 请代理再搜 = () => {
    if (活跃意向 === null) return;
    void 操作.刷新候选岗位(活跃意向).catch((错误: unknown) => 轻提示(P4错误文案(错误)));
  };

  // 从「在谈」子视图点放大镜时本页还没挂载，顶部意向栏把意图存进模块级信号，
  // 这里挂载后取走并展开搜索行（取走即复位，下次进来不会自己弹开）
  useEffect(() => {
    const 待办 = 取走市场工具请求();
    if (待办 === '搜索') 设搜索展开(true);
  }, []);

  // 搜索行展开就把光标送进输入框，省用户一次点击
  useEffect(() => {
    if (搜索展开) 搜索框.current?.focus();
  }, [搜索展开]);

  // 标注意见 #9：切意向后市场职位流跟着变；
  // 「不感兴趣」的岗在这一步就被剔除 —— 用户说过不想再看见，它不该再参与后面任何一步。
  // 被屏蔽的公司同样剔除：屏蔽在本产品里是双向的（你看不到它、它也匹配不到你），
  // 举报层里勾了「同时屏蔽」之后回到这一屏还能看见它的岗，那个承诺就是假的。
  // P4：Backend 完全不读 市场列表（列表只来自候选岗位快照），Mock 原样保留这套过滤。
  const 屏蔽公司 = useMemo(
    () => new Set(状态.屏蔽名单.map((条) => 条.名称)),
    [状态.屏蔽名单]
  );
  const 本意向市场 = useMemo(
    () =>
      (是后端
        ? []
        : 市场列表.filter((岗) => {
          if (岗.意向 !== 状态.当前意向) return false;
          if (状态.不感兴趣岗位.includes(岗.编号)) return false;
          if (屏蔽公司.has(岗.公司)) return false;
          // 已委托代理去谈的岗要退出市场流：它已经变成一张在谈单，继续留在待选列表里
          // 就是一张点不动的死卡 —— 委托 8 个岗就永久堵 8 张，而且会让用户反过来怀疑
          // 「我到底委托成功没有」（还在待选列表 = 看起来像没委托上）。
          // 只有本次进屏里刚点的那张先留着显示委托状态标，把这一下的反馈给足，
          // 下次进来才移出 —— 企业端 候选推荐 的已接触推荐就是这个口径，照它写。
          if (状态.已委托.includes(岗.编号) && !本次已委托.current.has(岗.编号)) return false;
          return true;
        })),
    [是后端, 状态.当前意向, 状态.不感兴趣岗位, 屏蔽公司, 状态.已委托]
  );

  const 关键词 = 搜索词.trim().toLowerCase();
  const 显示列表 = useMemo(
    () => 本意向市场.filter((岗) => 命中搜索(岗, 关键词)),
    [本意向市场, 关键词]
  );
  // Task 5：待选流 = 权威快照减去「进屏前就已开案」的卡（它已经是一张在谈单）；
  // 本次进屏点过、随后被权威投影确认成功的那张先留在原位显示状态标，顺序不变。
  // 只是渲染投影：不动 P4 原始缓存、不删详情坐标、不结束任何 Case。
  const 后端待选 = useMemo(
    () => 后端卡们.filter(({ 视图, 展示 }) => !P4已开案(展示)
      || 本次委托.current.has(委托键(视图.intentionId ?? '', 视图.jobId))),
    [后端卡们]
  );
  // 用户主动的本地搜索照常生效：暂留不绕过用户自己的筛选
  const 后端显示 = useMemo(
    () => 后端待选.filter(({ 视图 }) => 命中搜索(视图.卡, 关键词)),
    [后端待选, 关键词]
  );

  // Backend 列表态：无活跃意向 / 首载进行中 / 首载失败（给明确重试）；
  // 已有卡的快照不管阶段（刷新失败保留旧卡，错误单独一行交代）都算「有卡」。
  const 后端列表态: '无活跃意向' | '载入中' | '失败' | '有卡' =
    活跃意向 === null
      ? '无活跃意向'
      : 后端快照 === undefined ||
          (后端快照.items.length === 0 &&
            (后端快照.阶段 === '未开始' || 后端快照.阶段 === '进行中'))
        ? '载入中'
        : 后端快照 !== undefined && 后端快照.items.length === 0 && 后端快照.阶段 === '失败'
          ? '失败'
          : '有卡';

  // （顶栏原「筛选 · N ▾」角标的生效规则数计算随删筛选一起删除，2026-09-09 产品负责人定稿）

  // 需要你协调的条数从在谈列表实时算，横幅文案与「在谈」子视图保持一致，
  // 免得同一句话在两个子视图里给出不同数字。
  const 待协调数 = 状态.在谈列表.filter((单) => 单.需要你).length;

  // Backend MatchCase 真相源：横幅复用在谈首页同一 在谈范围 的 P5 快照投影
  // （与「在谈」子视图逐字同口径）。看市场只消费已在内存的快照：不注册 P5 scope、
  // 不发任何 P5 请求 —— 直达没有快照时与在谈首载同口径显示「正在读入在谈职位…」，
  // 绝不拿 legacy 在谈列表 冒充待办数。
  // 横幅 scope 与 P4 列表、在谈首页共用同一个有效当前 ID（不按意向名反查）
  const 在谈范围档 = 状态.在谈范围;
  const 横幅filterRef = 在谈范围档 === '全部' ? null : 活跃意向;
  const 有横幅scope = 活跃意向 !== null || 在谈范围档 === '全部';
  const 横幅快照 = 有横幅scope
    ? 后端状态.P5工作区?.[P5范围键.open('candidate', 横幅filterRef)]
    : undefined;
  const 当前SubjectId = 后端状态.主体?.last_used_role === 'candidate'
    ? 后端状态.主体.subject_id
    : null;
  const 横幅状态 = 取P5候选横幅状态(横幅快照, 当前SubjectId, 有横幅scope);
  const 横幅强调 = 是后端
    ? 横幅状态.强调
    : (待协调数 > 0 ? `${待协调数} 个职位需要你协调` : '暂时没有需要你介入的');

  const 关闭搜索 = () => {
    设搜索展开(false);
    设搜索词('');
  };

  return (
    <主页外壳>
      <顶部意向栏 打开搜索={() => 设搜索展开(true)} />

      {搜索展开 ? (
        <div className={样式.搜索行}>
          <div className={样式.搜索框}>
            <放大镜图标 尺寸={16} 色="#a7aa9f" />
            <input
              ref={搜索框}
              className={样式.搜索输入}
              value={搜索词}
              placeholder="搜职位、公司或关键词"
              enterKeyHint="search"
              onChange={(事件) => 设搜索词(事件.target.value)}
            />
            {搜索词 ? (
              <button
                className={`${样式.搜索清空} 可点`}
                onClick={() => 设搜索词('')}
                aria-label="清空搜索"
              >
                ✕
              </button>
            ) : null}
          </div>
          <button className={`${样式.搜索取消} 可点`} onClick={关闭搜索}>
            取消
          </button>
        </div>
      ) : (
        // 搜索时把代理横幅让出去：这一刻用户是自己在找岗，屏幕该留给结果
        <代理横幅
          前文="初筛与前几轮我已谈完，"
          强调={横幅强调}
          // 交付 G：Backend 的代理页是导航说明而非自由对话，入口文案不许承诺「问AI代理」；
          // Mock 保持默认「问AI代理 ›」
          动作文={是后端 ? '查看代理功能 ›' : undefined}
          按下={() => 跳转(路径.问AI代理)}
        />
      )}

      {/* 横幅与列表之间的固定留白（RN 里是一个 height:10 的占位 View） */}
      <div style={{ height: 10, flex: 'none' }} />

      <下拉刷新 刷新={是后端 ? 重读当前范围 : undefined}>
      <滚动区>
        <div className={样式.列表}>
          {是后端 ? (
            <>
              {/* 刷新未决（POST 成功 / follow-up GET 失败）：旧卡保留，错误单独一行交代 */}
              {后端快照?.error && 后端卡们.length > 0 && !后端快照.刷新中 ? (
                <div className={样式.空态说明} style={{ padding: '0 4px 6px' }}>
                  {后端快照.error}
                </div>
              ) : null}
              {后端列表态 === '无活跃意向' ? (
                <div className={样式.空态}>
                  <div className={样式.空态标题}>还没有进行中的求职意向</div>
                  <div className={样式.空态说明}>代理只替进行中的意向看市场，先去补一条求职意向吧。</div>
                </div>
              ) : 后端列表态 === '载入中' ? (
                <div className={样式.空态}>
                  <div className={样式.空态标题}>正在为你挑岗位…</div>
                </div>
              ) : 后端列表态 === '失败' ? (
                <div className={样式.空态}>
                  <div className={样式.空态标题}>推荐暂时加载不了</div>
                  <div className={样式.空态说明}>{后端快照?.error}</div>
                  <button className={`${样式.空态主键} 可点`} onClick={重读当前范围}>
                    重试
                  </button>
                </div>
              ) : 后端显示.length === 0 ? (
                <空结果 搜索词={搜索词.trim()} 问代理={请代理再搜} />
              ) : (
                后端显示.map(({ 视图, 卡, 展示 }) => {
                  // 状态槽只认 映射P4委托展示 的闭合六态：进行中给状态标、开案带服务端 Case
                  // 才给「查看进展」、终态给禁用的权威文案（附上服务端拒绝原因，如有）
                  const 委托进度未知 = 展示?.inProgress === true && 卡.delegation !== null
                    && 进度未知.has(卡.delegation.delegation_id);
                  // 开案成功（case_started + 非空 case_id）用本页 Mock 已有的成功文案，
                  // 不再显示「已创建真实在谈」，也不给 Case 导航（Spec §7.1）
                  const 委托文字 = P4已开案(展示)
                    ? 'AI代理已接手'
                    : 委托进度未知
                      ? P4委托进度未知文案
                      : 展示 === null
                        ? '让AI代理去谈'
                        : `${展示.copy}${展示.reason === null ? '' : `：${展示.reason}`}`;
                  return (
                    <市场卡
                      key={卡.recommendation_id}
                      岗={视图.卡}
                      已委托={展示 !== null}
                      已委托文字={委托文字}
                      委托禁用={委托中.has(委托键(视图.intentionId ?? '', 视图.jobId))}
                      委托={() => void 开始委托(视图)}
                      // 带上有限来源标记 + 会话内来路证据：详情页据此走安全返回
                      //（直链/无标记/刷新残留标记则摆好主壳状态再替换进主壳）
                      按下={() => {
                        标记看市场来路();
                        跳转(路径.职位详情(视图.jobId), { 来源: 'candidate-market' });
                      }}
                    />
                  );
                })
              )}
            </>
          ) : (
            <>
              {显示列表.length === 0 ? (
                <空结果 搜索词={搜索词.trim()} 问代理={() => 跳转(路径.问AI代理)} />
              ) : (
                显示列表.map((岗) => (
                  <市场卡
                    key={岗.编号}
                    岗={岗}
                    已委托={状态.已委托.includes(岗.编号)}
                    委托={() => {
                      // 先记本次，再派发：否则这一派发就把卡从列表里过滤掉，
                      // 用户看不到「AI代理已接手」那一下，只看到卡凭空消失
                      本次已委托.current.add(岗.编号);
                      派发({ 型: '委托入谈', 岗 });
                    }}
                    按下={() => 跳转(路径.职位详情(岗.编号))}
                  />
                ))
              )}
            </>
          )}
        </div>
      </滚动区>
      </下拉刷新>

      {待选择委托 ? (
        // 多份附件：必须单选一份才可确认；取消 / 遮罩 / Esc 都只清捕获零请求，
        // 确认值只来自所选行的当前 file/version，层内文案声明授权仅对这一次委托生效
        <附件简历选择层
          文件们={待选择委托.文件们}
          取消={() => 设待选择委托(null)}
          确认={(选择) => {
            const 捕获 = 待选择委托;
            设待选择委托(null); // 先收层再发委托：失败要求下一次重新选
            if (捕获) void 执行候选委托(捕获.视图, 选择);
          }}
        />
      ) : null}

      {待确认委托 ? (
        // 不可逆动作的披露确认：正文点名这次提交哪份 PDF、披露什么，且仅对这一次
        // 委托生效；取消 / 遮罩 / Esc 都是零请求零状态，确认后才发起委托
        <确认层
          标题="确认委托AI代理？"
          正文={`S0 通过后，本 Case 将提交「${待确认委托.选择.displayName}」这份 PDF，并向该招聘方披露姓名和联系方式。本次授权仅对这一次委托生效。`}
          执行文="确认委托"
          取消文="暂不委托"
          取消={() => 设待确认委托(null)}
          执行={() => void 执行候选委托(待确认委托.视图, 待确认委托.选择)}
        />
      ) : null}
    </主页外壳>
  );
}

/** 空态：把「为什么没结果」和「下一步能干什么」一起给出来，
 *  搜不到时的出口是代理 —— 本地包含匹配搜不到，不代表市场上没有。
 *  本地档位筛选删掉之后就只剩两种空法：搜没搜着，和本来就没有。 */
function 空结果({ 搜索词, 问代理 }: { 搜索词: string; 问代理: () => void }) {
  const 有搜索 = 搜索词 !== '';

  const 标题 = 有搜索 ? `没有匹配「${搜索词}」的职位` : '这个意向下暂时没有新职位';
  const 说明 = 有搜索
    ? '这里只在已推荐的岗位里找。市场上还有没推给你的，让代理去搜一轮。'
    : '代理还在替你筛，有合适的会推过来。';

  return (
    <div className={样式.空态}>
      <div className={样式.空态标题}>{标题}</div>
      <div className={样式.空态说明}>{说明}</div>
      <button className={`${样式.空态主键} 可点`} onClick={问代理}>
        让AI代理帮我搜
      </button>
    </div>
  );
}

// （原「底部层：告诉AI代理你的硬性要求」筛选层 —— 全局规则 + 意向级规则一排一条的规则清单，
//   Backend 只读 / Mock 可编辑 —— 已于 2026-09-09 随删筛选整体删除；规则的增改删一律去 规则库 页。）

/** 单张市场职位卡。
 *  骨架与「在谈卡」完全一致（公司头行 → 职位名 → 标签行），唯一的差别在最下面那一段：
 *  在谈卡是「阶段 + 需要你 + 下一步」，市场卡是「发布人 + 让AI代理去谈」。
 *  用户点了「让AI代理去谈」，这张卡就原样长出下半段搬到在谈列表里 —— 同一张卡的两个状态，
 *  所以两边不能长得不一样（用户口径 2026-08-18）。
 *
 *  这里刻意不用「白卡 按下=…」整卡可点：卡内还有两个自己的按钮（› 和 去谈键），
 *  HTML 里 button 不能嵌套 button，所以外层用不可点的白卡，卡主体单独做一个按钮。 */
function 市场卡({
  岗,
  已委托,
  委托,
  按下,
  已委托文字 = 'AI代理已接手',
  委托禁用 = false,
}: {
  岗: 市场职位;
  已委托: boolean;
  委托: () => void;
  按下: () => void;
  /** 状态标文字；Backend 按闭合六态给权威文案，轮询连败时被「进度未知」的中性文案覆盖 */
  已委托文字?: string;
  /** Backend 反馈/委托写进行中时禁用去谈键（并发写会被操作层单飞丢弃） */
  委托禁用?: boolean;
}) {
  // 分从行来(2026-08-31):卡上的环与职位详情的环同一份计算分
  const 计算适配分 = use适配分(岗);
  return (
    <白卡 类名={样式.卡}>
      {/* 卡主体整块点进职位详情 */}
      <button className={`${样式.卡主体} 可点`} onClick={按下}>
        {/* 公司头行：字标 + 公司名/简介 + 右列[适配环 + 薪资]，与在谈卡一比一 */}
        <div className={样式.公司头行}>
          <公司字标 首字={岗.公司首字} 公司名={岗.公司} 尺寸={34} 圆角={10} 字号={14} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div className={`${样式.公司名} 单行`}>{岗.公司}</div>
            <div className={`${样式.公司简介} 单行`}>{岗.公司简介}</div>
          </div>
          <div className={样式.右列}>
            <适配环 分={计算适配分} 标={null} />
            <span className={`${样式.薪资} 薪资体`}>{岗.薪资.replace('-', '–')}</span>
          </div>
        </div>

        {/* 职位名 */}
        <div className={`${样式.职位名} 单行`}>{岗.职位}</div>

        {/* 标签行：岗位属性，与在谈卡同一口径（城市 · 区 / N 薪 / 办公方式 / 到岗） */}
        <div className={样式.标签行}>
          {岗.标签.map((标签) => (
            <span key={标签} className={样式.标签}>
              {标签}
            </span>
          ))}
        </div>
      </button>

      {/* 底行 —— 在谈卡在这个位置是「阶段 + 下一步」，市场卡是「发布人 + 去谈」。
          公司名头行已交代过，发布人若以公司名开头就只留身份段（如「企业直招」），不重复 */}
      <div className={样式.底行}>
        <span
          className={样式.发布人头像}
          style={{ background: 岗.发布人底色, color: 岗.发布人字色 }}
        >
          {岗.发布人首字}
        </span>
        <span className={`${样式.发布人} 单行`}>
          {岗.发布人.startsWith(`${岗.公司} · `) ? 岗.发布人.slice(岗.公司.length + 3) : 岗.发布人}
        </span>

        <button className={`${样式.尖括号} 可点`} onClick={按下} aria-label="查看职位详情">
          ›
        </button>

        {已委托 ? (
          // 一切委托态（含开案成功）都是不可点的状态标 —— 成功槽不再是「查看进展」，
          // 也不绑定任何 Case 导航；看职位详情仍走卡上原来的 › 入口（Spec §7.1）
          <span className={样式.已委托}>
            <span className={样式.已委托文字}>{已委托文字}</span>
          </span>
        ) : (
          <button
            className={`${样式.去谈键} 可点`}
            disabled={委托禁用}
            onClick={委托}
          >
            <谈判图标 />
            <span className={样式.去谈文字}>让AI代理去谈</span>
          </button>
        )}
      </div>
    </白卡>
  );
}
