// A15 我的Tab · 状态入口 + 功能宫格
//
// 版式（从上到下）：右上两枚工具图标（切换身份 / 设置）→ 头像行（56 圆头像 + 姓名 +
// 状态胶囊）→ 四个统计数 → 代理状态毛玻璃卡 → 常用/其他功能宫格 → 页脚小字。
// 数值全部照 RN 版（duixi-app/应用/屏幕/我的.js）与设计稿 A15 一比一搬。
//
// 屏内只有「功能宫格 + 页脚」这一段滚动，上半部分（头像 / 统计 / 代理卡）钉住不动 ——
// 这是设计稿的意图：个人状态是常驻信息，功能入口才是可翻的列表。

import { useEffect, useState, type ComponentType } from 'react';
import 样式 from './我的.module.css';
import { 主页外壳, 滚动区 } from '../组件/通用';
import {
  齿轮图标,
  身份切换图标,
  简历图标,
  靶心图标,
  旗帜图标,
  禁止图标,
  层级图标,
  归档图标,
  问号图标,
} from '../组件/图标';
import 代理标 from '../组件/代理标';
import { use导航 } from '../路由/导航钩子';
import { 路径 } from '../路由/路径表';
import { 我的信息 } from '../数据/模拟数据';
import { use应用状态 } from '../状态/应用状态';
import { P5范围键 } from '../状态/后端/MatchCase操作';
import { 取P5Open统计 } from '../状态/后端/MatchCase统计';

/** 图标.tsx 里所有图标共用的属性签名 —— 宫格数据里要存「图标组件本身」，所以需要这个类型 */
type 图标组件 = ComponentType<{ 尺寸?: number; 色?: string; 线宽?: number }>;

/** 宫格里的一格。目标为 null 表示原型里还没有对应屏，点了给一条浮层提示 */
interface 宫格条目 {
  名称: string;
  图标: 图标组件;
  目标: string | null;
}

/** 统计行的一格。按下 = 这个数字可点，落到对应的在谈列表档；不给 按下 就是纯展示 */
interface 统计格 {
  数值: string;
  名称: string;
  色: string;
  按下?: () => void;
}

/** 统计数的取色：模拟数据里存的是语义色名，这里翻成 CSS 变量（对齐 RN 版的三档配色） */
function 取统计色(色名: string): string {
  if (色名 === '深绿') return 'var(--深绿)';
  if (色名 === '次要') return 'var(--次要浅)';
  return 'var(--墨)';
}

export default function 我的() {
  const { 跳转 } = use导航();
  const { 状态, 派发, 数据源模式, 后端状态, 操作 } = use应用状态();
  // 身份文案分两套投影：Backend 只认权威事实 —— 姓名没填就给中性占位，状态胶囊认
  // 服务端简历快照（没水合到 = 资料暂不可用；水合到了但 status 为空 = 未填写，绝不拿
  // 表单默认「在职」或 Mock 的「在职 · 保密求职中」充数）。Mock 继续走原型兜底文案，
  // 演示观感不变。头像首字也只在 Backend 取权威姓名，避免占位文案被拆出一个假「姓」。
  const 是后端 = 数据源模式 === 'backend';
  const 权威姓名 = 状态.基本信息.真名.trim();
  const 姓名 = 是后端
    ? 权威姓名 || '未填写姓名'
    : 权威姓名 || 我的信息.姓名;
  const 头像首字 = 是后端 ? 权威姓名.charAt(0) : 姓名.charAt(0);
  const 状态文案 = 是后端
    ? 后端状态.简历快照 === null
      ? '资料暂不可用'
      : 后端状态.简历快照.profile.status === ''
        ? '未填写求职状态'
        : 状态.基本信息.身份
    : 我的信息.状态;
  const 头像 = 状态.求职头像;

  // P6：规则计数只认已水合的权威规则 —— Backend 未水合时不出计数（宁缺勿错，
  // 不把 Mock 种子数当真，与 规则库 门控同一口径）
  const 可显示候选规则数 = 数据源模式 === 'mock' || 后端状态.Agent规则水合.candidate.rules === '成功';
  const 生效规则数 =
    状态.全局规则.filter((条) => 条.生效).length +
    状态.意向级规则.filter((条) => 条.生效).length;

  // Backend MatchCase 真相源：四项统计与候选代理卡数字只读当前 candidate/owner 的
  // 权威 summary。首次加载、每次挂载刷新、失败或 owner 不匹配都显示 —；不回退分页或 Mock。
  const P5Scope = P5范围键.summary('candidate');
  const 当前SubjectId = 后端状态.主体?.last_used_role === 'candidate'
    ? 后端状态.主体.subject_id
    : null;
  const Backend统计 = 取P5Open统计(后端状态.P5摘要.candidate, 当前SubjectId);

  // 进屏 / 换主体：注册 summary 可见范围并权威刷新（与 P5 列表同款栅栏）；
  // 离开本屏清回 null。Mock 分支不注册、零 P5 请求。
  useEffect(() => {
    if (!是后端 || 当前SubjectId === null) return;
    操作.设置P5范围('candidate', P5Scope);
    void 操作.加载摘要('candidate').catch(() => undefined);
    return () => 操作.设置P5范围('candidate', null);
  }, [是后端, 当前SubjectId, P5Scope, 操作]);

  // 四个统计数改成从真实状态算：在详情页接受/退出之后，这里要立刻跟着变，
  // 否则用户做完决策回到「我的」看到的还是建档时写死的数字。
  //
  // 「在谈」不可点（2026-08-25 用户裁定）：它此前派发「看全部在谈」，
  // 那个动作会改写主页的持久状态（子视图切「在谈」、范围切「全部」），
  // 用户从「我的」点完回到主页发现整个主页被换了档 —— 主页不该被「我的」影响。
  // 「待你拍」保留可点：它读的是**全量**在谈单（跨意向），落到「全部意向」档（拦路 6）。
  // 其余数（初筛中 / 已归档）没有对应的档位，保持不可点，不做假入口。
  const 原Mock统计: 统计格[] = [
    {
      数值: String(状态.在谈列表.length),
      名称: '在谈',
      色: '墨',
    },
    {
      数值: String(状态.在谈列表.filter((条) => 条.阶段 === '匿名初筛').length),
      名称: '初筛中',
      色: '深绿',
    },
    {
      数值: String(状态.在谈列表.filter((条) => 条.需要你).length),
      名称: '待你拍',
      色: '深绿',
      按下: () => 派发({ 型: '看全部在谈', 档: '待我拍板' }),
    },
    { 数值: String(状态.归档列表.length), 名称: '已归档', 色: '次要' },
  ];
  const 统计: 统计格[] = 是后端 ? [
    {
      数值: Backend统计.open,
      名称: '在谈',
      色: '墨',
    },
    {
      数值: Backend统计.anonymousScreening,
      名称: '初筛中',
      色: '深绿',
    },
    {
      数值: Backend统计.needsAction,
      名称: '待你拍',
      色: '深绿',
      按下: () => 派发({ 型: '看全部在谈', 档: '待我拍板' }),
    },
    { 数值: Backend统计.archived, 名称: '已归档', 色: '次要' },
  ] : 原Mock统计;

  // 尚未实现的入口（屏蔽名单 / 帮助与客服 / 右上三枚工具图标）点了弹一条浮层提示，
  // 保证每个可点元素都有真实反馈，而不是按下去毫无动静的死按钮
  const [提示, 设提示] = useState<string | null>(null);
  useEffect(() => {
    if (!提示) return;
    const 定时器 = window.setTimeout(() => 设提示(null), 1600);
    return () => window.clearTimeout(定时器);
  }, [提示]);

  const 常用功能: 宫格条目[] = [
    { 名称: '我的简历', 图标: 简历图标, 目标: 路径.我的简历 },
    { 名称: '求职意向', 图标: 靶心图标, 目标: 路径.求职意向管理 },
    { 名称: 'AI代理规则库', 图标: 旗帜图标, 目标: 路径.规则库 },
    { 名称: '屏蔽名单', 图标: 禁止图标, 目标: 路径.屏蔽名单 },
  ];
  const 其他功能: 宫格条目[] = [
    { 名称: '披露偏好', 图标: 层级图标, 目标: 路径.披露偏好 },
    // 宫格名即屏上文案：2026-08-22 随全站「接洽」→「代谈」一起改（定名理由见 在谈详情.tsx），
    // 企业端同一格的名称必须逐字一致（企业我的.tsx）
    { 名称: '历史代谈', 图标: 归档图标, 目标: 路径.归档谈判 },
    { 名称: '帮助与客服', 图标: 问号图标, 目标: 路径.帮助与客服 },
  ];

  /** 宫格 / 工具图标的统一点击：有目标就跳转，没有就提示 */
  const 打开 = (目标: string | null, 名称: string) => {
    if (目标) 跳转(目标);
    else 设提示(`${名称} 正在开发中`);
  };

  return (
    <主页外壳 白底>
      {/* ── 右上工具行：切换身份 / 设置 ── */}
      <div className={样式.工具行}>
        {/* 切身份进选身份页让用户自己挑，而不是直接甩到另一端（标注意见 2026-08-18）*/}
        <button
          className={`${样式.工具键} 可点`}
          onClick={() => 跳转(路径.切换身份自求职端)}
          aria-label="切换身份"
        >
          <身份切换图标 />
        </button>
        <button
          className={`${样式.工具键} 可点`}
          onClick={() => 跳转(路径.设置)}
          aria-label="设置"
        >
          <齿轮图标 />
        </button>
      </div>

      {/* ── 头像行：整行可点，进「个人信息」（账号身份:头像/姓名/联系方式）。
             2026-08-26 用户裁定:点名字/头像看到的应该是"我是谁",不是简历——
             简历入口在下方常用功能宫格,与这里不再重复;招聘端镜像是 招聘名片 ── */}
      <button className={`${样式.头像行} 可点`} onClick={() => 跳转(路径.个人信息)}>
        <span className={样式.头像}>
          {头像 ? <img className={样式.头像图} src={头像} alt="" /> : 头像首字}
        </span>
        <span className={样式.头像信息}>
          <span className={`${样式.姓名} 单行`}>{姓名}</span>
          <span className={样式.状态行}>
            <span className={`${样式.状态胶囊} 单行`}>{状态文案}</span>
          </span>
        </span>
        <span className={样式.尖括号}>›</span>
      </button>

      {/* ── 四个统计数：在谈 / 初筛中 / 待你拍 / 已归档。
             带 按下 的两格渲染成 button（可点，进对应的在谈列表档），其余仍是 div ── */}
      <div className={样式.统计行}>
        {统计.map((项) =>
          项.按下 ? (
            <button key={项.名称} className={`${样式.统计项} 可点`} onClick={项.按下}>
              <span className={`${样式.统计数} 等宽数字`} style={{ color: 取统计色(项.色) }}>
                {项.数值}
              </span>
              <span className={样式.统计名}>{项.名称}</span>
            </button>
          ) : (
            <div key={项.名称} className={样式.统计项}>
              <span className={`${样式.统计数} 等宽数字`} style={{ color: 取统计色(项.色) }}>
                {项.数值}
              </span>
              <span className={样式.统计名}>{项.名称}</span>
            </div>
          )
        )}
      </div>

      {/* ── 代理状态毛玻璃卡：压在顶部渐变头上，「管理 ›」进规则库 ── */}
      <button className={`${样式.代理卡} 可点`} onClick={() => 跳转(路径.规则库)}>
        <代理标
          尺寸={30}
          脸色="#ffffff"
          眼色="var(--墨)"
          描边色="var(--墨)"
          描边宽={2.6}
        />
        <span className={样式.代理文字}>
          <span className={样式.代理标题行}>
            <span className={样式.代理标题}>我的求职AI代理</span>
            {/* 在线绿点：代理正在后台并行谈判的可视信号（Backend 没有 runtime presence
                合同，不得声称在线） */}
            {!是后端 ? <span className={样式.在线点} /> : null}
          </span>
          <span className={`${样式.代理状态} 单行`}>
            {是后端
              ? '当前 MatchCase：' + Backend统计.open
              : '在线 · 正在跟进 ' + 状态.在谈列表.length + ' 个机会'}
            {/* 规则计数未水合时（Backend）整段不出，不渲染 0 也不拿 Mock 数充数 */}
            {可显示候选规则数 ? (
              <> · 规则 {生效规则数} 条生效</>
            ) : null}
          </span>
        </span>
        <span className={样式.管理}>管理 ›</span>
      </button>

      {/* ── 功能宫格区：屏内唯一滚动容器，底部留 130 给悬浮玻璃导航 ── */}
      <滚动区>
        <div className={样式.功能区}>
          <宫格卡 标题="常用功能" 项目={常用功能} 打开={打开} 主色 />
          <宫格卡 标题="其他功能" 项目={其他功能} 打开={打开} />
          {/* 占位运营页脚没有合同来源（热线/许可证均未确认），只在 Mock 渲染 */}
          {!是后端 ? (
            <div className={样式.页脚}>
              服务热线 400-000-0000 · 工作时间 8:00–22:00
              <br />
              人力资源服务许可证 · 算法举报 · 资质证照
            </div>
          ) : null}
        </div>
      </滚动区>

      {/* 浮层提示：未实现入口的兜底反馈，1.6 秒后自动消失 */}
      {提示 ? <div className={样式.浮层提示}>{提示}</div> : null}
    </主页外壳>
  );
}

/**
 * 功能宫格卡：白卡 + 标题 + 4 列图标格。
 * 主色 = true 时图标底用淡绿底 + 深绿描线（常用功能），否则用浅灰底 + 次要色（其他功能），
 * 靠这一层颜色差把「常用」和「其他」在视觉上分开，而不用额外的分组标题层级。
 */
function 宫格卡({
  标题,
  项目,
  打开,
  主色 = false,
}: {
  标题: string;
  项目: 宫格条目[];
  打开: (目标: string | null, 名称: string) => void;
  主色?: boolean;
}) {
  return (
    <div className={样式.宫格卡}>
      <div className={样式.宫格标题}>{标题}</div>
      <div className={样式.宫格}>
        {项目.map((项) => {
          const 图标 = 项.图标;
          return (
            <button
              key={项.名称}
              className={`${样式.宫格项} 可点`}
              onClick={() => 打开(项.目标, 项.名称)}
            >
              <span className={`${样式.宫格图标底} ${主色 ? '' : 样式.次色底}`}>
                <图标 色={主色 ? 'var(--深绿)' : 'var(--次要)'} />
              </span>
              <span className={样式.宫格名}>{项.名称}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
